'use strict';

/** Sliding-window rate limiter keyed by an arbitrary string (uid, ip, ...). In-memory, per process. */
class RateLimiter {
  constructor({ now = Date.now } = {}) {
    this.now = now;
    this.buckets = new Map();
  }

  /** @returns {boolean} true if the action is allowed (and is counted). */
  allow(key, max, windowMs) {
    const t = this.now();
    let hits = this.buckets.get(key);
    if (!hits) {
      hits = [];
      this.buckets.set(key, hits);
    }
    while (hits.length && hits[0] <= t - windowMs) hits.shift();
    if (hits.length >= max) return false;
    hits.push(t);
    return true;
  }

  /** Drops empty/expired buckets (call periodically). */
  sweep(windowMs = 3600 * 1000) {
    const t = this.now();
    for (const [k, hits] of this.buckets) {
      while (hits.length && hits[0] <= t - windowMs) hits.shift();
      if (hits.length === 0) this.buckets.delete(k);
    }
  }
}

module.exports = { RateLimiter };

