    turnSecret: env.TURN_SECRET || '',
    turnUrls: list(env.TURN_URLS),
    stunUrls: list(env.STUN_URLS || 'stun:stun.l.google.com:19302'),
    turnTtlSeconds: parseInt(env.TURN_TTL_SECONDS || '3600', 10),
    turnRequestsPerMinute: parseInt(env.TURN_REQUESTS_PER_MINUTE || '20', 10),
    testTamper: env.FREECALL_TEST_TAMPER || '',
